function historySearchMatches(rawText) {
  const normalized = rawText.toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ı/g, "i");
  const stopWords = new Set(["tarih", "tarihi", "tarihce", "ozet", "ozetle", "liste", "tablo", "soru", "sor", "yaz", "hikaye", "senaryo", "sinav", "test", "hakkinda", "bilgi", "goster", "ver", "bir", "icin", "ve", "detay", "ara", "goster"]);
  const terms = normalized.split(/[^a-z0-9]+/i).filter(t => t && !stopWords.has(t));
  if (!terms.length) return [];
  return state.historyItems.map(h => {
    const searchable = [h.cat, h.period, h.title, h.summary, h.places, ...(h.people || []), ...(h.keywords || h.concepts || [])].join(" ").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ı/g, "i");
    let score = 0;
    terms.forEach(term => {
      if ((h.title || "").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 5;
      if ((h.period || "").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 4;
      if ((h.places || "").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 3;
      if ((h.people || []).join(" ").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 3;
      if (searchable.includes(term)) score += 1;
    });
    return { item: h, score };
  }).filter(match => match.score > 0).sort((a, b) => b.score - a.score).map(match => match.item);
}

