160:     function historySearchMatches(rawText) {
161:       const normalized = rawText.toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ı/g, "i");
162:       const stopWords = new Set(["tarih", "tarihi", "tarihce", "ozet", "ozetle", "liste", "tablo", "soru", "sor", "yaz", "hikaye", "senaryo", "sinav", "test", "hakkinda", "bilgi", "goster", "ver", "bir", "icin", "ve", "detay", "ara", "goster"]);
163:       const terms = normalized.split(/[^a-z0-9]+/i).filter(t => t && !stopWords.has(t));
164:       if (!terms.length) return [];
165:       return state.historyItems.map(h => {
166:         const searchable = [h.cat, h.period, h.title, h.summary, h.places, ...(h.people || []), ...(h.keywords || h.concepts || [])].join(" ").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ı/g, "i");
167:         let score = 0;
168:         terms.forEach(term => {
169:           if ((h.title || "").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 5;
170:           if ((h.period || "").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 4;
171:           if ((h.places || "").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 3;
172:           if ((h.people || []).join(" ").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 3;
173:           if (searchable.includes(term)) score += 1;
174:         });
