      ],
      historyItems: [
        { cat: "Tarih Öncesi", date: "~3,3 milyon yıl önce – MÖ 10.000", period: "~3,3 milyon yıl önce – MÖ 10.000", title: "Taş Aletler ve İnsanlığın Uzun Başlangıcı", summary: "İlk taş aletlerden Homo sapiens’in Afrika’da ortaya çıkışına ve kıtalara yayılışına uzanan Paleolitik dönem. Tarihleme yeni bulgularla değişebilir.", places: "Doğu Afrika (Olduvai, Koobi Fora); Güney Afrika; Levant; Avrasya; Sahul", people: ["Homo habilis", "Homo erectus", "Homo sapiens"], keywords: ["Paleolitik", "avcı-toplayıcılık", "ateş", "göç", "Homo sapiens"], concepts: ["Paleolitik", "avcı-toplayıcılık", "ateş", "göç", "Homo sapiens"] },
