        { cat: "Kavramların Tarihi", period: "MÖ ~3.200 – günümüz", title: "Yazı, Arşiv ve Bilginin Saklanması", summary: "İdari kil tabletlerden el yazmalarına, matbaadan dijital arşivlere uzanan kayıt teknolojileri bilginin kim tarafından üretildiğini ve korunduğunu şekillendirdi.", places: "Uruk; İskenderiye; Bağdat; Mainz; dünya kütüphaneleri ve dijital ağlar", concepts: ["çivi yazısı", "kütüphane", "matbaa", "arşiv", "dijital koruma"] },
        { cat: "Kavramların Tarihi", period: "MÖ ~7. yüzyıl – günümüz", title: "Para, Pazarlar ve Finans", summary: "Sikke, kâğıt para, bankacılık ve elektronik ödemeler farklı toplumlarda farklı zamanlarda gelişti; para biçimleri güven ve kurumlara dayanır.", places: "Lidya ve Ege; İpek Yolu; Amsterdam ve Londra; küresel ödeme ağları", concepts: ["sikke", "kredi", "bankacılık", "merkez bankası", "dijital ödeme"] },
        { cat: "Kavramların Tarihi", period: "Antik takvimler – atom saati", title: "Zamanı Ölçmek: Takvim ve Saat", summary: "Güneş ve Ay döngülerini izleyen takvimlerden mekanik saatlere ve atomik zaman standardına geçiş, tarım ve gündelik yaşamı küresel koordinasyona bağladı.", places: "Stonehenge; Babil; İskenderiye; Greenwich; uluslararası zaman laboratuvarları", concepts: ["ay-güneş takvimi", "artık yıl", "mekanik saat", "UTC", "atom saati"] },
        { cat: "Kavramların Tarihi", period: "Antik haritalar – uydu çağı", title: "Haritalar, Navigasyon ve Dünya Tasavvuru", summary: "Sözlü coğrafya ve portolanlardan basılı atlaslara, uydu görüntüsü ve coğrafi bilgi sistemlerine uzanan haritalar hem yön bulma aracı hem de güç ve mülkiyet anlatısıdır.", places: "Akdeniz; İpek Yolu; Piri Reis haritası; Greenwich; yörüngedeki uydular", concepts: ["kartografya", "pusula", "boylam", "Piri Reis", "GIS"] },
        { cat: "Kavramların Tarihi", period: "19. yüzyıl – günümüz", title: "İletişim: Telgraftan İnternet ve Yapay Zekâya", summary: "Telgraf, telefon, radyo, televizyon ve internet mesajların hızını ve erişimini artırdı; yeni medya her dönemde mahremiyet ve bilgi güveni soruları doğurdu.", places: "Londra ve Kalküta telgraf hattı; Bell laboratuvarları; ARPANET düğümleri; küresel ağlar", concepts: ["telgraf", "radyo", "ARPANET", "internet", "yapay zekâ"] }
      ]
    };
    function updateClock() {
      document.getElementById("live-clock").textContent = "🕒 " + new Intl.DateTimeFormat("tr-TR", { timeZone: "Europe/Istanbul", dateStyle: "full", timeStyle: "medium" }).format(new Date());
    }
    setInterval(updateClock, 1000); updateClock();
    function refreshDailyAndTech(manual = false) {
      const now = new Date();
      const dayStr = new Intl.DateTimeFormat("tr-TR", { timeZone: "Europe/Istanbul", dateStyle: "full" }).format(now);
      const timeStr = new Intl.DateTimeFormat("tr-TR", { timeZone: "Europe/Istanbul", timeStyle: "medium" }).format(now);
      document.getElementById("daily-stamp").textContent = "Günlük paket: " + dayStr;
      document.getElementById("tech-stamp").textContent = "Son kontrol: " + timeStr;
      document.getElementById("sync-status").textContent = manual ? "Manuel yenilendi (" + timeStr + ")" : "Aktif • Otomatik yenileme açık";
      renderAgenda(); renderTech();
    }
    function renderAgendaFilters() { document.getElementById("agenda-filters").innerHTML = AGENDA_CATEGORIES.map(c => `<button class="btn ${state.activeAgendaCat === c ? "active" : ""}" onclick="selectAgendaCat('${c}')">${c}</button>`).join(""); }
    window.selectAgendaCat = function(c) { state.activeAgendaCat = c; renderAgendaFilters(); renderAgenda(); };
    function renderAgenda() {
      const items = state.activeAgendaCat === "Tümü" ? state.agendaItems : state.agendaItems.filter(x => x.cat.toLowerCase() === state.activeAgendaCat.toLowerCase());
      state.lastShownAgenda = items;
      document.getElementById("agenda-list").innerHTML = items.map((item, i) => `<article class="item"><div><span class="tag">#${i + 1} • ${item.cat}</span><span class="meta">${item.source}</span></div><div style="font-weight:700; margin-top:6px;">${item.title}</div><button class="btn" style="margin-top:8px; padding:5px 10px; font-size:0.78rem;" onclick="togglePanel('ag-${i}')">Detay & Güncel Durum</button><div class="detail-panel" id="ag-${i}"><strong>Özet:</strong> ${item.summary}<br/><strong>Güncel Durum:</strong> ${item.currentState}</div></article>`).join("");
    }
    function renderTech() { document.getElementById("tech-list").innerHTML = state.techItems.map(t => `<article class="item"><div><span class="tag tech">${t.tag}</span></div><div style="font-weight:700; margin-top:6px;">${t.title}</div><p style="margin-top:4px; font-size:0.86rem; color:#cbd5e1;">${t.detail}</p></article>`).join(""); }
    function renderHistoryFilters() { document.getElementById("history-filters").innerHTML = HISTORY_CATEGORIES.map(c => `<button class="btn ${state.activeHistoryCat === c ? "active" : ""}" onclick="selectHistoryCat('${c}')">${c}</button>`).join(""); }
    window.selectHistoryCat = function(c) { state.activeHistoryCat = c; renderHistoryFilters(); renderHistory(); };
    function renderHistory() {
      const term = document.getElementById("history-search").value.trim().toLocaleLowerCase("tr-TR");
      const items = state.historyItems.filter(h => {
        const inCategory = state.activeHistoryCat === "Tümü" || h.cat === state.activeHistoryCat;
        const searchable = [h.cat, h.period, h.title, h.summary, h.places, ...h.concepts].join(" ").toLocaleLowerCase("tr-TR");
        return inCategory && (!term || searchable.includes(term));
      });
      document.getElementById("history-count").textContent = `${items.length} / ${state.historyItems.length} kayıt · Tarih Öncesi → 2026`;
      document.getElementById("history-list").innerHTML = items.length ? items.map(h => `<article class="item history-item"><div><span class="tag hist">${h.cat}</span><span class="meta">${h.period}</span></div><div style="font-weight:700; margin-top:6px;">${h.title}</div><p style="margin-top:4px; font-size:0.86rem; color:#cbd5e1;">${h.summary}</p><div class="history-facts"><span><b>📍 Mekânlar:</b> ${h.places}</span></div><div class="history-concepts" aria-label="Anahtar kavramlar">${h.concepts.map(c => `<span class="concept">${c}</span>`).join("")}</div></article>`).join("") : `<div class="empty-state">Bu aramada kayıt bulunamadı. Başka bir dönem, mekân veya kavram deneyin.</div>`;
    }
    document.getElementById("history-search").addEventListener("input", renderHistory);
    window.togglePanel = function(id) { const el = document.getElementById(id); if (el) el.classList.toggle("open"); };
    function historySearchMatches(rawText) {
      const normalized = rawText.toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ı/g, "i");
      const stopWords = new Set(["tarih", "tarihi", "tarihce", "ozet", "ozetle", "liste", "tablo", "soru", "sor", "yaz", "hikaye", "senaryo", "sinav", "test", "hakkinda", "bilgi", "goster", "ver", "bir", "icin", "ve", "detay", "ara", "goster"]);
      const terms = normalized.split(/[^a-z0-9]+/i).filter(t => t && !stopWords.has(t));
      if (!terms.length) return [];
      return state.historyItems.map(h => {
        const searchable = [h.cat, h.period, h.title, h.summary, h.places, ...(h.people || []), ...(h.keywords || h.concepts || [])].join(" ").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ı/g, "i");
        let score = 0;
        terms.forEach(term => {
          if ((h.title || "").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 5;
          if ((h.period || "").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 4;
          if ((h.places || "").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 3;
          if ((h.people || []).join(" ").toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes(term)) score += 3;
          if (searchable.includes(term)) score += 1;
        });
        return { item: h, score };
      }).filter(match => match.score > 0).sort((a, b) => b.score - a.score).map(match => match.item);
    }
    function runQuery(rawText) {
      const q = rawText.trim().toLowerCase();
      const numMatch = q.match(/(\d+)\s*\.?\s*(gündem|haber|madde|sıra|detay)?/);
      if (numMatch && (q.includes("gündem") || q.includes("haber") || q.includes("detay") || q.includes("madde") || q.trim().length <= 10)) {
        const idx = parseInt(numMatch[1], 10) - 1; const found = state.lastShownAgenda[idx];
        return found ? `<strong>#${idx + 1} ${found.cat} — ${found.title}</strong><br/>${found.summary}<br/><span class="meta">Durum: ${found.currentState}</span>` : `Listedeki ${idx + 1}. kayıt bulunamadı.`;
      }
      if (/(tarih|tarihçe|antik|orta çağ|modern|icat|köken|tarih öncesi|2026)/i.test(q)) {
        const matches = historySearchMatches(rawText);
        if (!matches.length) return "<strong>🏛️ Tarih Arşivi:</strong> Bu sorguyla arşivde eşleşen gerçek bir kayıt bulunamadı.";
        return "<strong>🏛️ Tarih Arşivi · Tarih Öncesi → 2026:</strong><br/>" + matches.map(m => `• <strong>[${m.period} · ${m.cat}] ${m.title}:</strong> ${m.summary} <span class=\"meta\">Mekânlar: ${m.places} · Kavramlar: ${(m.keywords || m.concepts).join(", ")}</span>`).join("<br/>");
      }
      if (/(teknoloji|yapay zeka|ai|çip|robot|uzay|gelişen)/i.test(q)) return "<strong>⚡ Gelişen Teknoloji:</strong><br/>" + state.techItems.map(t => `• <strong>[${t.tag}] ${t.title}:</strong> ${t.detail}`).join("<br/>");
      return "Gündem, teknoloji veya tarihçe için anahtar kelime ya da sayısal gündem sırası (örn: '2. gündem detayı') girebilirsiniz.";
    }
    document.getElementById("query-form").addEventListener("submit", (e) => { e.preventDefault(); const inp = document.getElementById("query-input"); if (!inp.value.trim()) return; document.getElementById("query-output").innerHTML = runQuery(inp.value); inp.value = ""; });
    document.getElementById("force-refresh-btn").addEventListener("click", () => refreshDailyAndTech(true));
    renderAgendaFilters(); renderHistoryFilters(); refreshDailyAndTech(false);
    setInterval(() => refreshDailyAndTech(false), 5 * 60 * 1000);

</script>
<script>
(() => { const toggle=document.getElementById("legacyToggle"); const panel=document.getElementById("chronopulseLegacy"); if(toggle&&panel)toggle.addEventListener("click",()=>panel.classList.toggle("open")); })();
</script>
</body>
</html>'

