   ,{ cat: "Erken Modern", era: "Erken Modern", date: "~1450’ler", location: "Mainz; Avrupa", people: ["Johannes Gutenberg"], keywords: ["matbaa", "hareketli metal harf", "basılı kitap", "bilginin dolaşımı"], title: "Gutenberg’in Matbaası ve Avrupa’da Basılı Kitap", summary: "15. yüzyıl ortalarında Mainz’da geliştirilen hareketli metal harfli baskı, kitap üretimini ve metinlerin dolaşımını dönüştürdü; baskı teknolojisinin başka bölgelerde daha eski örnekleri vardı." }
   ,{ cat: "Erken Modern", era: "Erken Modern", date: "1517–1648", location: "Kutsal Roma İmparatorluğu; Avrupa", people: ["Martin Luther", "Jean Calvin"], keywords: ["Reformasyon", "95 Tez", "Protestanlık", "Augsburg Barışı", "Vestfalya Barışı"], title: "Reformasyon ve Avrupa’daki Dinsel Dönüşüm", summary: "1517’de Luther’in eleştirileriyle simgeleşen Reformasyon, Avrupa’da yeni Protestan geleneklerin oluşmasına ve uzun süreli siyasal-dinsel çatışmalara yol açtı; süreç tek bir olayla sınırlı değildi." }
   ,{ cat: "Modern Çağ", era: "Modern Çağ", date: "1789–1799", location: "Fransa; Paris; Avrupa", people: ["XVI. Louis", "Maximilien Robespierre", "Olympe de Gouges"], keywords: ["Fransız Devrimi", "1789", "cumhuriyet", "yurttaşlık", "İnsan ve Yurttaş Hakları Bildirisi"], title: "Fransız Devrimi ve Yurttaşlık Siyaseti", summary: "1789’da başlayan devrim monarşiyi devirerek cumhuriyeti ve yeni yurttaşlık tartışmalarını gündeme taşıdı; eşitlik ve hak iddiaları, kadınların ve sömürge halklarının dışlanmasıyla birlikte tartışmalı kaldı." }
   ,{ cat: "Modern Çağ", era: "Modern Çağ", date: "1868", location: "Japonya; Edo (Tokyo); Kyoto", people: ["İmparator Meiji", "Saigō Takamori", "Ōkubo Toshimichi"], keywords: ["Meiji Restorasyonu", "Tokugawa şogunluğu", "merkezileşme", "sanayileşme", "Japonya"], title: "Meiji Restorasyonu ve Japonya’nın Dönüşümü", summary: "1868’de Tokugawa şogunluğunun sona ermesiyle başlayan Meiji dönemi, merkezî devletin güçlenmesi ve hızlı kurumsal, askerî ve ekonomik dönüşümlerle karakterize edildi." }
   ,{ cat: "Çağdaş Dönem", era: "Çağdaş Dönem", date: "1945", location: "San Francisco; New York; küresel diplomasi", people: ["Birleşmiş Milletler kurucu üyeleri"], keywords: ["Birleşmiş Milletler", "BM Şartı", "uluslararası düzen", "kolektif güvenlik"], title: "Birleşmiş Milletler’in Kuruluşu", summary: "BM Şartı 26 Haziran 1945’te San Francisco’da imzalandı ve 24 Ekim’de yürürlüğe girdi; örgüt, savaş sonrası uluslararası iş birliği ve kolektif güvenlik için kuruldu." }
   ,{ cat: "Kavramların Tarihi", era: "Kavramların Tarihi", date: "17.–18. yüzyıllar", location: "İngiltere; Fransa; Avrupa siyasal düşüncesi", people: ["Thomas Hobbes", "John Locke", "Jean-Jacques Rousseau"], keywords: ["toplum sözleşmesi", "egemenlik", "rıza", "doğal haklar", "siyasal meşruiyet"], title: "Toplum Sözleşmesi ve Siyasal Meşruiyet", summary: "Hobbes, Locke ve Rousseau farklı toplum sözleşmesi kuramları geliştirdi; bu düşünceler siyasal otoritenin kaynağı, halkın rızası ve haklar üzerine modern tartışmaları etkiledi, ancak tek ve ortak bir kuram oluşturmadı." }
   ,{ cat: "Bilim, Teknoloji ve İcatlar", era: "Bilim, Teknoloji ve İcatlar", date: "1796", location: "Berkeley, Gloucestershire; Londra", people: ["Edward Jenner"], keywords: ["çiçek hastalığı", "aşılama", "inek çiçeği", "immünoloji", "halk sağlığı"], title: "Jenner ve Çiçek Hastalığına Karşı Aşılama (1796)", summary: "Edward Jenner 1796’da inek çiçeği materyaliyle çiçek hastalığına karşı koruma sağlayan uygulamasını sınadı; aşılama fikrinin daha eski örnekleri bulunduğundan modern aşılamanın başlangıcı tek kişiye indirgenemez." }
   ,{ cat: "Bilim, Teknoloji ve İcatlar", era: "Bilim, Teknoloji ve İcatlar", date: "1947", location: "Bell Laboratuvarları; Murray Hill, New Jersey", people: ["John Bardeen", "Walter Brattain", "William Shockley"], keywords: ["transistör", "katı hâl elektroniği", "bilgisayar", "yarı iletken"], title: "Transistörün Gösterilmesi (1947)", summary: "Bell Laboratuvarlarında Bardeen ve Brattain 1947’de ilk çalışan nokta-temaslı transistörü gösterdi; Shockley daha sonra bağlantı transistörünün geliştirilmesinde önemli rol oynadı." }
